%calculate appearance under D65
[xyz,xyzw]=spd2xyz(D65,obs,0,sampleset);

%calculate jab coordinates
jab=xyz2camucs(xyz,xyzw);

%select only samples within hue interval thetas
[usesamples,Nsamples,h]=selectsampleswithinhueinterval(jab(:,2:3),thetas);


% %display selected samples
global plotsamplesofmetrics
if plotsamplesofmetrics==1;
    srgb=xyz2srgb(xyz);

    figure,
    for i=1:size(sampleset,2)-1;

        subplot(4,5,i);imshow(rgb2Image(srgb(i,:),[200,200]));
        if usesamples(i)==1;
            title(sprintf('h = %1.2f --> sample is used.',h(i)))
        else
            title(sprintf('h = %1.2f --> sample is NOT used.',h(i)))

        end
    end
